package org.eink.inkprobe.notebook;

import java.nio.charset.StandardCharsets;
import java.nio.file.*;

/** Execute the actual stationary View presentation and input guards, not just PDF raster flags. */
public final class NotebookRestingPaperTest {
    private static String source(String name)throws Exception{return new String(Files.readAllBytes(Paths.get("app/src/main/java/org/eink/inkprobe/notebook/"+name+".java")),StandardCharsets.UTF_8);}
    private static String method(String source,String signature){return NotebookWorkspaceActivationTest.method(source,signature);}
    public static void main(String[] args)throws Exception{presentation();activity();pending();}
    private static void presentation()throws Exception{
        String production=source("NotebookRestingPaper").replaceAll("(?m)^package .*;\\s*|^import .*;\\s*","").replace("final class NotebookRestingPaper","static final class NotebookRestingPaper");
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;public class RestingPresentationFixture {",
            "static class Context {}static class Rect {int left=110,top=220,right=150,bottom=260;Rect(){}Rect(Rect r){left=r.left;top=r.top;right=r.right;bottom=r.bottom;}public boolean equals(Object o){if(!(o instanceof Rect))return false;Rect r=(Rect)o;return left==r.left&&top==r.top&&right==r.right&&bottom==r.bottom;}boolean isEmpty(){return false;}}",
            "static class Canvas {int depth,holes;int save(){return ++depth;}void clipOutRect(int a,int b,int c,int d){if(a!=10||b!=20||c!=50||d!=60)throw new AssertionError(\"pane coordinates\");holes++;}void restoreToCount(int n){depth=n-1;}}",
            "static class View {static final int IMPORTANT_FOR_ACCESSIBILITY_NO=2;int invalidates;View(Context c){}protected void onDraw(Canvas c){}void setClickable(boolean b){if(b)throw new AssertionError(\"captures touches\");}void setFocusable(boolean b){if(b)throw new AssertionError(\"captures focus\");}void setImportantForAccessibility(int n){}void invalidate(){invalidates++;}boolean post(Runnable r){r.run();return true;}}",
            "static class FrameLayout {static class LayoutParams {LayoutParams(int w,int h){if(w!=-1||h!=-1)throw new AssertionError(\"paper must fill pane\");}}final List<View> children=new ArrayList<>();void getLocationOnScreen(int[] p){p[0]=100;p[1]=200;}void addView(View v,int index,LayoutParams p){children.add(index,v);}void removeView(View v){children.remove(v);}}",
            production,
            "static class Listener implements NotebookRestingPaper.Listener {boolean ready=true,fail;int draws,errors;Canvas last;public boolean ready(){return ready;}public void draw(Canvas c){last=c;draws++;if(fail)throw new IllegalStateException(\"draw failed\");}public List<Rect> exclusions(){return Collections.singletonList(new Rect());}public void failed(Throwable error){errors++;}}",
            "static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static void run(){Context context=new Context();FrameLayout anchor=new FrameLayout();View nativeInk=new View(context);anchor.children.add(nativeInk);Listener listener=new Listener();NotebookRestingPaper p=new NotebookRestingPaper(context,anchor,listener);p.show();check(anchor.children.equals(Arrays.asList(p.content,nativeInk)),\"ordinary paper is a child below native live ink, with no foreground window to conceal pen trails\");Canvas hardware=new Canvas();p.content.onDraw(hardware);check(listener.last==hardware&&listener.draws==1&&hardware.holes==1&&hardware.depth==0,\"direct View canvas reaches complete paper renderer without a native paper bitmap\");p.refresh();int frames=p.content.invalidates;p.refresh();check(p.content.invalidates==frames,\"unchanged clock/status bounds do not repaint idle paper\");for(int i=0;i<4;i++)p.show();check(anchor.children.size()==2&&p.content.invalidates==frames+4,\"navigation, pen and fullscreen updates retain the same attached View\");listener.ready=false;p.content.onDraw(hardware);check(listener.draws==1,\"missing viewport does not draw invalid page coordinates\");listener.ready=true;listener.fail=true;p.content.onDraw(hardware);check(hardware.depth==0&&p.failed&&listener.errors==1&&anchor.children.contains(p.content),\"drawing failure reports a recoverable error without switching back to distorted native paper\");p.close();check(anchor.children.equals(Collections.singletonList(nativeInk)),\"disposal releases the paper child\");frames=p.content.invalidates;p.show();check(p.content.invalidates==frames,\"late callbacks cannot resurrect retired paper\");System.out.println(\"NotebookRestingPresentation: \"+checks+\" assertions passed (persistent View below native ink, direct canvas, clipping, failure and retirement).\");}}"
        );NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.RestingPresentationFixture",fixture);
    }
    private static void activity()throws Exception{
        String source=source("NotebookActivity"),layer=source("NotebookFigureLayer");
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;public class RestingActivityFixture {",
            "static class NotebookFigureLayer {static class Request {NotebookFigure figure;Request(NotebookFigure f){figure=f;}static Request inView(NotebookFigure f,NotebookViewport v,int p,float s){return new Request(f);}}",
            method(layer,"static List<Request> visible("),"}",
            "static class Ink {boolean pending,viewPaper;boolean usesViewPaper(){return viewPaper;}}static class Paper {int shows;void show(){shows++;}}static class Color {static final int WHITE=0xffffffff;}static class Canvas {int save,restores,white;void drawColor(int c){white++;}int save(){return ++save;}void translate(float x,float y){}void scale(float x,float y){}void restoreToCount(int n){restores++;}}",
            "final Ink ink=new Ink();final Paper restingPaper=new Paper();boolean editable=true,selectionViewPreview;Object selectionOutline,selection;int prepared,pagesDrawn,inkPages,boundaries,outlines,selectionScenes;NotebookViewport viewport=new NotebookViewport(1,400,600,200,300,12);final Map<Integer,NotebookPage> pages=new HashMap<>();float scrollY;boolean canEdit(){return editable;}void prepareStrokePaths(){prepared++;}void clipReadingPage(Canvas c,int id){}void drawPage(Canvas c,NotebookPage page,boolean includeInk,boolean preview){if(!preview)throw new AssertionError(\"clear preview must be composed\");pagesDrawn++;if(includeInk)inkPages++;}void drawPageBoundaries(Canvas c){boundaries++;}void drawSelectionOutline(Canvas c,int x,int y){outlines++;}void drawClearSelectionScene(Canvas c){selectionScenes++;}static byte[] pdf(){return \"%PDF-1.4\\nfixture\\n%%EOF\".getBytes(java.nio.charset.StandardCharsets.UTF_8);}static NotebookFigure markdown(){return NotebookFigure.markdown(UUID.randomUUID(),100,150,120,0,new NotebookMarkdown(\"hello $x$\",false,640,320,pdf(),640,480,pdf()));}",
            method(source,"private boolean restingPaperReady("),method(source,"private boolean hasVisibleMarkdown("),method(source,"private void refreshRestingPaper("),method(source,"private void drawRestingPaper("),
            "static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static void run(){RestingActivityFixture f=new RestingActivityFixture();NotebookPage plain=NotebookPage.empty().withSize(400,600);f.pages.put(1,plain);check(!f.restingPaperReady(),\"ordinary notes retain their original path until View paper is enabled\");f.pages.put(1,plain.withFigures(Collections.singletonList(markdown())));check(f.hasVisibleMarkdown(),\"visible Markdown enables the one-way native separation\");f.ink.viewPaper=true;f.refreshRestingPaper();check(f.restingPaper.shows==1&&f.prepared==1,\"paper includes prepared canonical ink\");Canvas canvas=new Canvas();f.drawRestingPaper(canvas);check(canvas.white==1&&f.pagesDrawn==1&&f.inkPages==1&&f.boundaries==1&&canvas.restores==1&&f.outlines==1,\"complete View scene includes paper, Markdown, saved ink, boundaries and lasso outline\");f.ink.pending=true;f.refreshRestingPaper();check(f.restingPaper.shows==2,\"live or pending native strokes cannot hide the clear paper below them\");f.editable=false;check(f.restingPaperReady(),\"scroll, zoom, modal edits and fullscreen cannot disable the clear paper\");f.selectionOutline=new Object();check(f.restingPaperReady(),\"lasso retains clear paper\");f.selectionViewPreview=true;f.selection=new Object();f.drawRestingPaper(canvas);check(f.selectionScenes==1,\"lasso movement uses the direct clear scene\");f.viewport=f.viewport.withView(8,1400);check(!f.hasVisibleMarkdown()&&f.restingPaperReady(),\"moving Markdown offscreen cannot switch back to native paper\");f.viewport=null;check(!f.restingPaperReady(),\"unconfigured geometry waits for viewport initialization\");System.out.println(\"NotebookRestingActivity: \"+checks+\" assertions passed (persistent eligibility across navigation, writing, fullscreen and lasso).\");}}"
        );NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.RestingActivityFixture",fixture);
    }
    private static void pending()throws Exception{
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;public class PendingPaperFixture {static class Gesture {boolean active;boolean isActive(){return active;}boolean isPending(){return active;}}boolean penDown;Object activePoints;final List<Object> awaitingCommit=new ArrayList<>(),nativeCommits=new ArrayList<>();final Gesture eraserCommit=new Gesture(),lassoGesture=new Gesture(),nativeLassoGesture=new Gesture(),lassoCompletion=new Gesture();",
            method(source("NotebookInk"),"public boolean hasPendingInput("),
            "public static void run(){PendingPaperFixture f=new PendingPaperFixture();if(f.hasPendingInput())throw new AssertionError(\"idle\");for(int kind=0;kind<8;kind++){f.penDown=kind==0;f.activePoints=kind==1?new Object():null;f.awaitingCommit.clear();f.nativeCommits.clear();if(kind==2)f.awaitingCommit.add(new Object());if(kind==3)f.nativeCommits.add(new Object());f.eraserCommit.active=kind==4;f.lassoGesture.active=kind==5;f.nativeLassoGesture.active=kind==6;f.lassoCompletion.active=kind==7;if(!f.hasPendingInput())throw new AssertionError(\"input guard \"+kind);}System.out.println(\"NotebookPendingPaper: 9 assertions passed (actual pen, commit, eraser and lasso gates).\");}}"
        );NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.PendingPaperFixture",fixture);
    }
}
